import{_ as t,a0 as l,w as o,s as c,ao as d,I as p,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 上安全传输文件的 14 SCP 命令示例 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安全传输文件的 14 SCP 命令示例 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安全传输文件的 14 SCP 命令示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安全传输文件的 14 SCP 命令示例 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191020 14 SCP Command Examples to Securely Transfer Files in Linux","title":"在 Linux 上安全传输文件的 14 SCP 命令示例","tag":"201912","desc":""},"relativePath":"201912/20191020 14 SCP Command Examples to Securely Transfer Files in Linux.md","filePath":"[post].md"}'),h={name:"201912/20191020 14 SCP Command Examples to Securely Transfer Files in Linux.md"};function r(u,s,g,k,b,x){const i=l("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="在-linux-上安全传输文件的-14-scp-命令示例" tabindex="-1">在 Linux 上安全传输文件的 14 SCP 命令示例 <a class="header-anchor" href="#在-linux-上安全传输文件的-14-scp-命令示例" aria-label="Permalink to “在 Linux 上安全传输文件的 14 SCP 命令示例”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201912/13/100239f31is1ios31vvoo3.jpg" alt=""></p><p>SCP（<ruby>安全复制<rt>Secure Copy</rt></ruby>）是 Linux 和 Unix 之类的系统中的命令行工具，用于通过网络安全地跨系统传输文件和目录。当我们使用 <code>scp</code> 命令将文件和目录从本地系统复制到远程系统时，则在后端与远程系统建立了 ssh 连接。换句话说，我们可以说 <code>scp</code> 在后端使用了相同的 SSH 安全机制，它需要密码或密钥进行身份验证。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/scp-command-examples-linux.jpg" alt="scp-command-examples-linux"></p><p>在本教程中，我们将讨论 14 个有用的 Linux <code>scp</code> 命令示例。</p><p><code>scp</code> 命令语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># scp &lt;选项&gt; &lt;文件或目录&gt; 用户名@目标主机:/&lt;文件夹&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># scp &lt;选项&gt; 用户名@目标主机:/文件 &lt;本地文件夹&gt;</span></span></code></pre></div><p><code>scp</code> 命令的第一个语法演示了如何将文件或目录从本地系统复制到特定文件夹下的目标主机。</p><p><code>scp</code> 命令的第二种语法演示了如何将目标主机中的文件复制到本地系统中。</p><p>下面列出了 <code>scp</code> 命令中使用最广泛的一些选项，</p><ul><li><code>-C</code> 启用压缩</li><li><code>-i</code> 指定识别文件或私钥</li><li><code>-l</code> 复制时限制带宽</li><li><code>-P</code> 指定目标主机的 ssh 端口号</li><li><code>-p</code> 复制时保留文件的权限、模式和访问时间</li><li><code>-q</code> 禁止 SSH 警告消息</li><li><code>-r</code> 递归复制文件和目录</li><li><code>-v</code> 详细输出</li></ul><p>现在让我们跳入示例！</p><h3 id="示例-1-使用-scp-将文件从本地系统复制到远程系统" tabindex="-1">示例：1）使用 scp 将文件从本地系统复制到远程系统 <a class="header-anchor" href="#示例-1-使用-scp-将文件从本地系统复制到远程系统" aria-label="Permalink to “示例：1）使用 scp 将文件从本地系统复制到远程系统”">​</a></h3><p>假设我们要使用 <code>scp</code> 命令将 jdk 的 rpm 软件包从本地 Linux 系统复制到远程系统（172.20.10.8），请使用以下命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp jdk-linux-x64_bin.rpm root@linuxtechi:/opt</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>jdk-linux-x64_bin.rpm                          100%   10MB  27.1MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>上面的命令会将 jdk 的 rpm 软件包文件复制到 <code>/opt</code> 文件夹下的远程系统。</p><h3 id="示例-2-使用-scp-将文件从远程系统复制到本地系统" tabindex="-1">示例：2）使用 scp 将文件从远程系统复制到本地系统 <a class="header-anchor" href="#示例-2-使用-scp-将文件从远程系统复制到本地系统" aria-label="Permalink to “示例：2）使用 scp 将文件从远程系统复制到本地系统”">​</a></h3><p>假设我们想将文件从远程系统复制到本地系统下的 <code>/tmp</code> 文件夹，执行以下 <code>scp</code> 命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp root@linuxtechi:/root/Technical-Doc-RHS.odt /tmp</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>Technical-Doc-RHS.odt                         100% 1109KB  31.8MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$ ls -l /tmp/Technical-Doc-RHS.odt</span></span>
<span class="line"><span>-rwx------. 1 pkumar pkumar 1135521 Oct 19 11:12 /tmp/Technical-Doc-RHS.odt</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-3-使用-scp-传输文件时的详细输出-v" tabindex="-1">示例：3）使用 scp 传输文件时的详细输出（-v） <a class="header-anchor" href="#示例-3-使用-scp-传输文件时的详细输出-v" aria-label="Permalink to “示例：3）使用 scp 传输文件时的详细输出（-v）”">​</a></h3><p>在 <code>scp</code> 命令中，我们可以使用 <code>-v</code> 选项启用详细输出。使用详细输出，我们可以轻松地发现后台确切发生了什么。这对于调试连接、认证和配置等问题非常有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~]$ scp -v jdk-linux-x64_bin.rpm root@linuxtechi:/opt</span></span>
<span class="line"><span>Executing: program /usr/bin/ssh host 172.20.10.8, user root, command scp -v -t /opt</span></span>
<span class="line"><span>OpenSSH_7.8p1, OpenSSL 1.1.1 FIPS  11 Sep 2018</span></span>
<span class="line"><span>debug1: Reading configuration data /etc/ssh/ssh_config</span></span>
<span class="line"><span>debug1: Reading configuration data /etc/ssh/ssh_config.d/05-redhat.conf</span></span>
<span class="line"><span>debug1: Reading configuration data /etc/crypto-policies/back-ends/openssh.config</span></span>
<span class="line"><span>debug1: /etc/ssh/ssh_config.d/05-redhat.conf line 8: Applying options for *</span></span>
<span class="line"><span>debug1: Connecting to 172.20.10.8 [172.20.10.8] port 22.</span></span>
<span class="line"><span>debug1: Connection established.</span></span>
<span class="line"><span>…………</span></span>
<span class="line"><span>debug1: Next authentication method: password</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span></code></pre></div><h3 id="示例-4-将多个文件传输到远程系统" tabindex="-1">示例：4）将多个文件传输到远程系统 <a class="header-anchor" href="#示例-4-将多个文件传输到远程系统" aria-label="Permalink to “示例：4）将多个文件传输到远程系统”">​</a></h3><p>可以使用 <code>scp</code> 命令一次性将多个文件复制/传输到远程系统，在 <code>scp</code> 命令中指定多个文件，并用空格隔开，示例如下所示</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp install.txt index.html jdk-linux-x64_bin.rpm root@linuxtechi:/mnt</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>install.txt                                      100%    0     0.0KB/s   00:00</span></span>
<span class="line"><span>index.html                                       100%   85KB   7.2MB/s   00:00</span></span>
<span class="line"><span>jdk-linux-x64_bin.rpm                            100%   10MB  25.3MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-5-在两个远程主机之间传输文件" tabindex="-1">示例：5）在两个远程主机之间传输文件 <a class="header-anchor" href="#示例-5-在两个远程主机之间传输文件" aria-label="Permalink to “示例：5）在两个远程主机之间传输文件”">​</a></h3><p>使用 <code>scp</code> 命令，我们可以在两个远程主机之间复制文件和目录，假设我们有一个可以连接到两个远程 Linux 系统的本地 Linux 系统，因此从我的本地 Linux 系统中，我可以使用 <code>scp</code> 命令在这两个系统之间复制文件，</p><p>命令语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># scp 用户名@远程主机1:/&lt;要传输的文件&gt; 用户名@远程主机2:/&lt;文件夹&gt;</span></span></code></pre></div><p>示例如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># scp root@linuxtechi:~/backup-Oct.zip root@linuxtechi:/tmp</span></span>
<span class="line"><span># ssh root@linuxtechi &quot;ls -l /tmp/backup-Oct.zip&quot;</span></span>
<span class="line"><span>-rwx------. 1 root root 747438080 Oct 19 12:02 /tmp/backup-Oct.zip</span></span></code></pre></div><h3 id="示例-6-递归复制文件和目录-r" tabindex="-1">示例：6）递归复制文件和目录（-r） <a class="header-anchor" href="#示例-6-递归复制文件和目录-r" aria-label="Permalink to “示例：6）递归复制文件和目录（-r）”">​</a></h3><p>在 <code>scp</code> 命令中使用 <code>-r</code> 选项将整个目录从一个系统递归地复制到另一个系统，示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -r Downloads root@linuxtechi:/opt</span></span></code></pre></div><p>使用以下命令验证 <code>Downloads</code> 文件夹是否已复制到远程系统，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ ssh root@linuxtechi &quot;ls -ld /opt/Downloads&quot;</span></span>
<span class="line"><span>drwxr-xr-x. 2 root root 75 Oct 19 12:10 /opt/Downloads</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-7-通过启用压缩来提高传输速度-c" tabindex="-1">示例：7）通过启用压缩来提高传输速度（-C） <a class="header-anchor" href="#示例-7-通过启用压缩来提高传输速度-c" aria-label="Permalink to “示例：7）通过启用压缩来提高传输速度（-C）”">​</a></h3><p>在 <code>scp</code> 命令中，我们可以通过使用 <code>-C</code> 选项启用压缩来提高传输速度，它将自动在源主机上启用压缩并在目标主机上解压缩。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~]$ scp -r -C Downloads root@linuxtechi:/mnt</span></span></code></pre></div><p>在以上示例中，我们正在启用压缩的情况下传输下载目录。</p><h3 id="示例-8-复制时限制带宽-l" tabindex="-1">示例：8）复制时限制带宽（-l） <a class="header-anchor" href="#示例-8-复制时限制带宽-l" aria-label="Permalink to “示例：8）复制时限制带宽（-l）”">​</a></h3><p>在 <code>scp</code> 命令中使用 <code>-l</code> 选项设置复制时对带宽使用的限制。带宽以 Kbit/s 为单位指定，示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -l 500 jdk-linux-x64_bin.rpm  root@linuxtechi:/var</span></span></code></pre></div><h3 id="示例-9-在-scp-时指定其他-ssh-端口-p" tabindex="-1">示例：9）在 scp 时指定其他 ssh 端口（-P） <a class="header-anchor" href="#示例-9-在-scp-时指定其他-ssh-端口-p" aria-label="Permalink to “示例：9）在 scp 时指定其他 ssh 端口（-P）”">​</a></h3><p>在某些情况下，目标主机上的 ssh 端口会更改，因此在使用 <code>scp</code> 命令时，我们可以使用 <code>-P</code> 选项指定 ssh 端口号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -P 2022 jdk-linux-x64_bin.rpm  root@linuxtechi:/var</span></span></code></pre></div><p>在上面的示例中，远程主机的 ssh 端口为 “2022”。</p><h3 id="示例-10-复制时保留文件的权限、模式和访问时间-p" tabindex="-1">示例：10）复制时保留文件的权限、模式和访问时间（-p） <a class="header-anchor" href="#示例-10-复制时保留文件的权限、模式和访问时间-p" aria-label="Permalink to “示例：10）复制时保留文件的权限、模式和访问时间（-p）”">​</a></h3><p>从源复制到目标时，在 <code>scp</code> 命令中使用 <code>-p</code> 选项保留权限、访问时间和模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -p jdk-linux-x64_bin.rpm  root@linuxtechi:/var/tmp</span></span>
<span class="line"><span>jdk-linux-x64_bin.rpm                            100%   10MB  13.5MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-11-在-scp-中以安静模式传输文件-q" tabindex="-1">示例：11）在 scp 中以安静模式传输文件（-q） <a class="header-anchor" href="#示例-11-在-scp-中以安静模式传输文件-q" aria-label="Permalink to “示例：11）在 scp 中以安静模式传输文件（-q）”">​</a></h3><p>在 <code>scp</code> 命令中使用 <code>-q</code> 选项可禁止显示 ssh 的传输进度、警告和诊断消息。示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -q -r Downloads root@linuxtechi:/var/tmp</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-12-在传输时使用-scp-中的识别文件-i" tabindex="-1">示例：12）在传输时使用 scp 中的识别文件（-i） <a class="header-anchor" href="#示例-12-在传输时使用-scp-中的识别文件-i" aria-label="Permalink to “示例：12）在传输时使用 scp 中的识别文件（-i）”">​</a></h3><p>在大多数 Linux 环境中，首选基于密钥的身份验证。在 <code>scp</code> 命令中，我们使用 <code>-i</code> 选项指定识别文件（私钥文件），示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -i my_key.pem -r Downloads root@linuxtechi:/root</span></span></code></pre></div><p>在上面的示例中，<code>my_key.pem</code> 是识别文件或私钥文件。</p><h3 id="示例-13-在-scp-中使用其他-ssh-config-文件-f" tabindex="-1">示例：13）在 scp 中使用其他 ssh_config 文件（-F） <a class="header-anchor" href="#示例-13-在-scp-中使用其他-ssh-config-文件-f" aria-label="Permalink to “示例：13）在 scp 中使用其他 ssh_config 文件（-F）”">​</a></h3><p>在某些情况下，你使用不同的网络连接到 Linux 系统，可能某些网络位于代理服务器后面，因此在这种情况下，我们必须具有不同的 <code>ssh_config</code> 文件。</p><p>通过 <code>-F</code> 选项在 <code>scp</code> 命令中指定了不同的 <code>ssh_config</code> 文件，示例如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]$ scp -F /home/pkumar/new_ssh_config -r Downloads root@linuxtechi:/root</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>jdk-linux-x64_bin.rpm                     100%   10MB  16.6MB/s   00:00</span></span>
<span class="line"><span>backup-Oct.zip                            100%  713MB  41.9MB/s   00:17</span></span>
<span class="line"><span>index.html                                100%   85KB   6.6MB/s   00:00</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><h3 id="示例-14-在-scp-命令中使用其他加密方式-c" tabindex="-1">示例：14）在 scp 命令中使用其他加密方式（-c） <a class="header-anchor" href="#示例-14-在-scp-命令中使用其他加密方式-c" aria-label="Permalink to “示例：14）在 scp 命令中使用其他加密方式（-c）”">​</a></h3><p>默认情况下，<code>scp</code> 使用 AES-128 加密方式来加密文件。如果你想在 <code>scp</code> 命令中使用其他加密方式，请使用 <code>-c</code> 选项，后接加密方式名称。</p><p>假设我们要在用 <code>scp</code> 命令传输文件时使用 3des-cbc 加密方式，请运行以下 <code>scp</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# scp -c 3des-cbc -r Downloads root@linuxtechi:/root</span></span></code></pre></div><p>使用以下命令列出 <code>ssh</code> 和 <code>scp</code> 支持的加密方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ssh -Q cipher localhost | paste -d , -s -</span></span>
<span class="line"><span>3des-cbc,aes128-cbc,aes192-cbc,aes256-cbc,root@linuxtechi,aes128-ctr,aes192-ctr,aes256-ctr,root@linuxtechi,root@linuxtechi,root@linuxtechi</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>以上就是本教程的全部内容，要获取有关 <code>scp</code> 命令的更多详细信息，请参考其手册页。请在下面的评论部分中分享你的反馈和评论。</p><hr>`,69)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/scp-command-examples-in-linux/"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/scp-command-examples-in-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=t(h,[["render",r]]);export{C as __pageData,y as default};
